package com.example.data.entity;

import androidx.room.Entity;
import androidx.room.Index;
import androidx.room.PrimaryKey;

/**
 * The gold-standard photo for one part.
 *
 * <p>{@code partType} is uniquely indexed, which is what makes saving a reference actually
 * replace the previous one. Without it, {@code OnConflictStrategy.REPLACE} had nothing to
 * conflict on — the primary key is autogenerated, so every save minted a fresh row — and the
 * lookup returned whichever row SQLite happened to visit first, in practice the oldest. A
 * part that had ever been skipped therefore kept resolving to its {@code dummy_placeholder}
 * no matter how many times an operator set a real photo, which blocked inspection and made
 * "replace this part's reference" silently do nothing.
 */
@Entity(tableName = "ReferenceProfile",
        indices = {@Index(value = "partType", unique = true)})
public class ReferenceProfile {

    /**
     * Stand-in {@code imageUri} for a part registered without a reference photo yet.
     *
     * <p>Public because the check "is this a real reference?" was written out by hand at five
     * call sites, each repeating both the sentinel string and the null guard around it. A
     * sixth that forgot either half would silently treat the placeholder as a photo and try
     * to decode it. Prefer {@link #hasRealImage()} over comparing against this directly.
     *
     * <p><b>Read-only now.</b> Nothing writes a placeholder since the "skip setup" button was
     * removed — a part is either given a labelled reference or has no profile row at all. The
     * sentinel stays because rows written by earlier builds are still on devices, and
     * {@link #hasRealImage()} is what keeps them from being decoded as photographs.
     */
    public static final String PLACEHOLDER_URI = "dummy_placeholder";

    @PrimaryKey(autoGenerate = true)
    private long id;
    private String partType; // e.g., "PART_A", "PART_B" or barcode/ID family
    private String imageUri;
    private long createdAt;

    public ReferenceProfile() {
    }

    public ReferenceProfile(String partType, String imageUri, long createdAt) {
        this.partType = partType;
        this.imageUri = imageUri;
        this.createdAt = createdAt;
    }

    public long getId() {
        return id;
    }

    public void setId(long id) {
        this.id = id;
    }

    public String getPartType() {
        return partType;
    }

    public void setPartType(String partType) {
        this.partType = partType;
    }

    public String getImageUri() {
        return imageUri;
    }

    public void setImageUri(String imageUri) {
        this.imageUri = imageUri;
    }

    /**
     * True when this profile points at an actual reference photo, rather than being absent
     * or still holding {@link #PLACEHOLDER_URI}.
     */
    public boolean hasRealImage() {
        return imageUri != null && !imageUri.isEmpty() && !PLACEHOLDER_URI.equals(imageUri);
    }

    public long getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(long createdAt) {
        this.createdAt = createdAt;
    }
}
